const CAM_MAP = {
  "harmonic sine roll": 0,
  "canted teardrop sweep": 1,
  "asymmetric ratchet jerk": 2,
  "triangular chisel pulse": 3,
  "stepped dwell snap": 4,
  "brutal square shock": 5
};

const TOPO_MAP = {
  "parallel surging rollers": 0,
  "intersecting cross wakes": 1,
  "concentric radial swell": 2,
  "spiraling vortex drift": 3,
  "checkerboard shear weave": 4,
  "stochastic turbulent churn": 5
};

const CAP_MAP = {
  "sheared flat slab": 0,
  "canted beveled chisel": 1,
  "fluted cylindrical socket": 2,
  "recessed square core": 3,
  "stepped telescope crown": 4,
  "pronged castellated tooth": 5
};

const ILLUM_MAP = {
  "high noon crest": 0,
  "oblique morning rake": 1,
  "sharp twilight skim": 2,
  "grazing dusk silhouette": 3,
  "low amber eclipse": 4,
  "contrasting split beacon": 5
};

const PACE_MAP = {
  "glacial hydraulic heave": 0.002,
  "steady monolithic stroke": 0.0073,
  "brisk mechanical cadence": 0.0191,
  "throbbing diesel gallop": 0.0387,
  "urgent pneumatic pulse": 0.0613,
  "feverish rattle tremor": 0.0937
};

const GRID_SIZE = 22;
const TILE_W = 24;
const TILE_H = 12;
const BASE_Y = 550;
let time = 0;

p.setup = function() {
  p.createCanvas(800, 800);
  p.noStroke();
};

p.draw = function() {
  const camStr = p.getSynthVar("cam_profile") || "harmonic sine roll";
  const topoStr = p.getSynthVar("wave_topology") || "parallel surging rollers";
  const capStr = p.getSynthVar("piston_cap") || "sheared flat slab";
  const illumStr = p.getSynthVar("cast_illumination") || "high noon crest";
  const paceStr = p.getSynthVar("cadence_pace") || "glacial hydraulic heave";

  const camMode = CAM_MAP[camStr] ?? 0;
  const topoMode = TOPO_MAP[topoStr] ?? 0;
  const capMode = CAP_MAP[capStr] ?? 0;
  const illumMode = ILLUM_MAP[illumStr] ?? 0;
  const speed = PACE_MAP[paceStr] ?? 0.0073;

  time += speed * (1 + 0.03 * Math.sin(p.frameCount * 0.071));

  let cBg, cTop, cLeft, cRight;
  switch (illumMode) {
    case 0: cBg = '#a1b5c2'; cTop = '#f0f4f8'; cLeft = '#b6c6d3'; cRight = '#8e9eab'; break;
    case 1: cBg = '#d9c6b0'; cTop = '#ffeacc'; cLeft = '#d6b797'; cRight = '#a38a74'; break;
    case 2: cBg = '#2a3b4c'; cTop = '#718fa6'; cLeft = '#43586b'; cRight = '#202a35'; break;
    case 3: cBg = '#141115'; cTop = '#845749'; cLeft = '#4d322b'; cRight = '#1a110e'; break;
    case 4: cBg = '#4a2c11'; cTop = '#f2a65a'; cLeft = '#a86122'; cRight = '#4a2408'; break;
    case 5: cBg = '#111'; cTop = '#fff'; cLeft = '#00a8ff'; cRight = '#e84118'; break;
  }

  p.background(cBg);
  p.push();
  p.translate(p.width / 2, BASE_Y);

  const ctx = p.drawingContext;

  for (let depth = 0; depth < GRID_SIZE * 2; depth++) {
    let layerPillars = [];
    for (let x = 0; x < GRID_SIZE; x++) {
      let y = depth - x;
      if (y >= 0 && y < GRID_SIZE) {
        layerPillars.push({x, y});
      }
    }

    if (layerPillars.length === 0) continue;

    ctx.fillStyle = cRight;
    ctx.beginPath();
    for (let pos of layerPillars) {
      let d = getPillarData(pos.x, pos.y, topoMode, camMode);
      drawRightFace(ctx, d.sx, d.sy, d.h);
    }
    ctx.fill();

    ctx.fillStyle = cLeft;
    ctx.beginPath();
    for (let pos of layerPillars) {
      let d = getPillarData(pos.x, pos.y, topoMode, camMode);
      drawLeftFace(ctx, d.sx, d.sy, d.h);
    }
    ctx.fill();

    for (let pos of layerPillars) {
      let d = getPillarData(pos.x, pos.y, topoMode, camMode);
      drawTopCap(ctx, d.sx, d.sy, d.h, capMode, cTop, cLeft, cRight, d.rawZ);
    }
  }
  p.pop();
};

function getPillarData(x, y, topoMode, camMode) {
  let cx = GRID_SIZE / 2, cy = GRID_SIZE / 2;
  let phase = 0;

  if (topoMode === 0) phase = x * 0.15 + time;
  else if (topoMode === 1) phase = (x * 0.15 + time) + (y * 0.15 + time);
  else if (topoMode === 2) phase = p.dist(x, y, cx, cy) * 0.15 - time;
  else if (topoMode === 3) phase = p.atan2(y-cy, x-cx)/p.TWO_PI + p.dist(x, y, cx, cy)*0.1 - time;
  else if (topoMode === 4) phase = (x*0.4 + y*0.4 + time);
  else if (topoMode === 5) phase = p.noise(x*0.15, y*0.15, time*0.5) * 4;

  let tPhase = phase % 1.0;
  if (tPhase < 0) tPhase += 1.0;
  let z = 0;

  if (camMode === 0) z = 0.5 - 0.5 * p.cos(tPhase * p.TWO_PI);
  else if (camMode === 1) z = Math.pow(p.sin(tPhase * p.PI), 2.5);
  else if (camMode === 2) z = tPhase < 0.8 ? (tPhase/0.8) : (1 - (tPhase-0.8)/0.2);
  else if (camMode === 3) z = 1.0 - Math.abs((tPhase * 2) - 1.0);
  else if (camMode === 4) z = p.lerp(Math.floor(tPhase * 4) / 3, Math.floor((tPhase+0.1) * 4) / 3, 0.5);
  else if (camMode === 5) z = tPhase < 0.5 ? 0 : 1;

  if (camMode === 4 || camMode === 5) {
    z = z * 0.8 + 0.1;
  }

  const h = 20 + z * 180;
  const sx = (x - y) * TILE_W;
  const sy = (x + y) * TILE_H * 0.5;
  return { sx, sy, h, rawZ: z };
}

function drawRightFace(ctx, sx, sy, h) {
  ctx.moveTo(sx, sy - h);
  ctx.lineTo(sx + TILE_W, sy + TILE_H * 0.5 - h);
  ctx.lineTo(sx + TILE_W, sy + TILE_H * 0.5);
  ctx.lineTo(sx, sy);
  ctx.closePath();
}

function drawLeftFace(ctx, sx, sy, h) {
  ctx.moveTo(sx, sy - h);
  ctx.lineTo(sx - TILE_W, sy + TILE_H * 0.5 - h);
  ctx.lineTo(sx - TILE_W, sy + TILE_H * 0.5);
  ctx.lineTo(sx, sy);
  ctx.closePath();
}

function drawTopCap(ctx, sx, sy, h, capMode, cTop, cLeft, cRight, rawZ) {
  ctx.fillStyle = cTop;
  let ty = sy - h;

  if (capMode === 0) {
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H * 0.5); ctx.lineTo(sx + TILE_W, ty); ctx.lineTo(sx, ty + TILE_H * 0.5); ctx.lineTo(sx - TILE_W, ty);
    ctx.fill();
  } else if (capMode === 1) {
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H); ctx.lineTo(sx + TILE_W, ty); ctx.lineTo(sx, ty + TILE_H * 0.5); ctx.lineTo(sx - TILE_W, ty);
    ctx.fill();
  } else if (capMode === 2) {
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H * 0.5); ctx.lineTo(sx + TILE_W, ty); ctx.lineTo(sx, ty + TILE_H * 0.5); ctx.lineTo(sx - TILE_W, ty);
    ctx.fill();
    ctx.fillStyle = cRight;
    ctx.beginPath();
    ctx.ellipse(sx, ty, TILE_W*0.6, TILE_H*0.6, 0, 0, p.TWO_PI);
    ctx.fill();
  } else if (capMode === 3) {
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H * 0.5); ctx.lineTo(sx + TILE_W, ty); ctx.lineTo(sx, ty + TILE_H * 0.5); ctx.lineTo(sx - TILE_W, ty);
    ctx.fill();
    ctx.fillStyle = cRight;
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H*0.25); ctx.lineTo(sx + TILE_W*0.5, ty); ctx.lineTo(sx, ty + TILE_H*0.25); ctx.lineTo(sx - TILE_W*0.5, ty);
    ctx.fill();
  } else if (capMode === 4) {
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H * 0.5); ctx.lineTo(sx + TILE_W, ty); ctx.lineTo(sx, ty + TILE_H * 0.5); ctx.lineTo(sx - TILE_W, ty);
    ctx.fill();
    let th = rawZ * 20;
    ctx.fillStyle = cRight;
    ctx.beginPath(); ctx.moveTo(sx, ty - th); ctx.lineTo(sx+TILE_W*0.6, ty+TILE_H*0.3 - th); ctx.lineTo(sx+TILE_W*0.6, ty+TILE_H*0.3); ctx.lineTo(sx, ty); ctx.fill();
    ctx.fillStyle = cLeft;
    ctx.beginPath(); ctx.moveTo(sx, ty - th); ctx.lineTo(sx-TILE_W*0.6, ty+TILE_H*0.3 - th); ctx.lineTo(sx-TILE_W*0.6, ty+TILE_H*0.3); ctx.lineTo(sx, ty); ctx.fill();
    ctx.fillStyle = cTop;
    ctx.beginPath(); ctx.moveTo(sx, ty - TILE_H*0.3 - th); ctx.lineTo(sx+TILE_W*0.6, ty - th); ctx.lineTo(sx, ty+TILE_H*0.3 - th); ctx.lineTo(sx-TILE_W*0.6, ty - th); ctx.fill();
  } else if (capMode === 5) {
    ctx.beginPath();
    ctx.moveTo(sx, ty - TILE_H * 0.5); ctx.lineTo(sx + TILE_W, ty); ctx.lineTo(sx, ty + TILE_H * 0.5); ctx.lineTo(sx - TILE_W, ty);
    ctx.fill();
    if (rawZ > 0.8) {
      let pop = (rawZ - 0.8) * 50;
      ctx.fillStyle = cLeft; ctx.beginPath(); ctx.rect(sx - 4, ty - pop, 4, pop); ctx.fill();
      ctx.fillStyle = cRight; ctx.beginPath(); ctx.rect(sx, ty - pop, 4, pop); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.rect(sx - 4, ty - pop - 4, 8, 4); ctx.fill();
    }
  }
}
